const http = require('http');

function dockerRequest(method, path) {
  return new Promise((resolve, reject) => {
    const req = http.request({ socketPath: '/var/run/docker.sock', path, method }, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.end();
  });
}

const target = $json.target;
if (!target) {
  throw new Error('target (container name or ID) is required for target_type "docker"');
}

const beforeRes = await dockerRequest('GET', '/containers/' + encodeURIComponent(target) + '/json');
if (beforeRes.status !== 200) {
  throw new Error('Container not found: ' + target + ' (HTTP ' + beforeRes.status + ')');
}
const before = JSON.parse(beforeRes.body);

const restartRes = await dockerRequest('POST', '/containers/' + encodeURIComponent(target) + '/restart?t=2');

// Give the container a moment to come back up before re-inspecting --
// the health check needs at least one cycle to report a fresh status.
await new Promise((r) => setTimeout(r, 4000));

const afterRes = await dockerRequest('GET', '/containers/' + encodeURIComponent(target) + '/json');
const after = JSON.parse(afterRes.body);

return [{
  json: {
    incident_id: $json.incident_id,
    target_type: 'docker',
    target,
    before: {
      status: before.State.Status,
      health: before.State.Health ? before.State.Health.Status : null,
      pid: before.State.Pid,
      started_at: before.State.StartedAt,
    },
    remediation: { action: 'container restart', http_status: restartRes.status },
    after: {
      status: after.State.Status,
      health: after.State.Health ? after.State.Health.Status : null,
      pid: after.State.Pid,
      started_at: after.State.StartedAt,
    },
    remediated: after.State.Pid !== before.State.Pid,
  },
}];

const { execSync } = require('child_process');

const target = $json.target;
const namespace = $json.namespace;
if (!target) {
  throw new Error('target (deployment name) is required for target_type "kubernetes"');
}

function kubectlJson(args) {
  const out = execSync('kubectl ' + args, { encoding: 'utf-8', maxBuffer: 10 * 1024 * 1024 });
  return JSON.parse(out);
}

function summarizePods(podList) {
  return podList.items.map((p) => ({
    name: p.metadata.name,
    ready: p.status.containerStatuses ? p.status.containerStatuses.every((c) => c.ready) : false,
    restart_count: p.status.containerStatuses
      ? p.status.containerStatuses.reduce((sum, c) => sum + c.restartCount, 0)
      : 0,
  }));
}

const before = summarizePods(kubectlJson('get pods -n ' + namespace + ' -l app=' + target + ' -o json'));

execSync('kubectl rollout restart deployment/' + target + ' -n ' + namespace, { encoding: 'utf-8' });
const rolloutOutput = execSync(
  'kubectl rollout status deployment/' + target + ' -n ' + namespace + ' --timeout=60s',
  { encoding: 'utf-8' }
).trim();

const after = summarizePods(kubectlJson('get pods -n ' + namespace + ' -l app=' + target + ' -o json'));

return [{
  json: {
    incident_id: $json.incident_id,
    target_type: 'kubernetes',
    target,
    namespace,
    before,
    remediation: { action: 'kubectl rollout restart', rollout_output: rolloutOutput },
    after,
    remediated: after.length > 0 && before.length > 0 && after[0].name !== before[0].name,
  },
}];
